import itertools
import numpy as np

def solve_D_sigma(sigma, N):
    from scipy.optimize import linprog
    c = np.ones(N - 1)
    A_ub = []
    b_ub = []
    for k in range(N):
        for l in range(k + 1, N):
            row = np.zeros(N - 1)
            for j in range(k, l):
                row[j] = -1.0
            A_ub.append(row)
            b_ub.append(-1.0 / (sigma[k] + sigma[l]))

    res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub), bounds=(0, None), method='highs')
    if res.success:
        return 1.0 / res.fun
    else:
        return 0.0

def solve_N(N):
    max_D = 0
    for sigma in itertools.permutations(range(1, N + 1)):
        D_sigma = solve_D_sigma(sigma, N)
        if D_sigma > max_D:
            max_D = D_sigma
    return max_D

for n in range(2, 7):
    print(f"N={n}, D_N={solve_N(n)}")

