import numpy as np
from scipy.optimize import minimize
import itertools

def constraint_func(delta, sigma):
    N = len(sigma)
    constraints = []
    for k in range(N):
        for l in range(k + 1, N):
            val = 0
            for j in range(k, l):
                val += delta[j]
            constraints.append(val - 1.0 / (sigma[k] + sigma[l]))
    return np.array(constraints)

def solve_D_sigma_minimize(sigma):
    N = len(sigma)
    cons = {'type': 'ineq', 'fun': lambda delta: constraint_func(delta, sigma)}
    res = minimize(lambda d: np.sum(d), np.ones(N-1)/N, constraints=cons, bounds=[(0, None)]*(N-1))
    if res.success:
        return 1.0 / res.fun
    else:
        return 0.0

def solve_N_minimize(N):
    max_D = 0
    for sigma in itertools.permutations(range(1, N + 1)):
        D_sigma = solve_D_sigma_minimize(sigma)
        if D_sigma > max_D:
            max_D = D_sigma
    return max_D

